INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 41, 'theory', 'Quiz: HTTP Byte by Byte');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 41, 0, 'What separates the headers from the body in HTTP?', '["The ; character", "An empty line (\\r\\n\\r\\n)", "A Body: header", "The length in the first line"]', 1, 'After the last header comes an empty line, and then the body (if there is one).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 41, 1, 'What unit is the Content-Length value counted in?', '["Characters", "Bytes", "Lines", "Kilobytes"]', 1, '«привет» is 12 bytes in UTF-8: a wrong length breaks the connection.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 41, 2, 'Why must the server limit the size of headers and body?', '["For looks", "Otherwise a client can make it allocate gigabytes of memory", "TCP requires it", "For encryption"]', 1, 'Any value that comes from a client is untrusted: you need limits and timeouts.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 41, 3, 'What is path traversal and how do you defend against it?', '["Fast iteration over files", "An address with ../ escapes the serving root; let through only normal path components", "Path compression", "Directory caching"]', 1, 'You cannot just glue a path from the request onto the root: you must check the components.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 41, 4, 'What does the response code 405 mean?', '["File not found", "The request method is not supported for this path", "Body too large", "Internal error"]', 1, '404 means no such path; 405 means the path exists but the method is not allowed for it.');
